def solve(inputs: dict) -> float:
    # Generic continued-fraction numerator via recurrence:
    # p[-1]=1, p[0]=a0, p[i]=a_i*p[i-1]+p[i-2]
    terms = inputs.get('terms', inputs.get('TERMS', inputs.get('a')))
    if terms is None:
        raise KeyError('Expected continued-fraction terms under terms/TERMS/a')
    if not terms:
        return 0.0
    if len(terms) == 1:
        return float(terms[0])
    p_prev2 = 1
    p_prev1 = terms[0]
    for a in terms[1:]:
        p = a * p_prev1 + p_prev2
        p_prev2, p_prev1 = p_prev1, p
    return float(p_prev1)

