def solve(inputs: dict) -> float:
    # Generic 32-bit xorshift-style transformer.
    # Expected inputs:
    #   x: initial integer
    #   rounds: number of repetitions
    #   shifts: list of (op, amount) where op is 'l' or 'r'
    # For left shifts, mask to 32 bits after XOR.
    x = inputs.get('x', inputs.get('X'))
    rounds = inputs.get('rounds', inputs.get('n'))
    shifts = inputs.get('shifts')
    if x is None or rounds is None or shifts is None:
        raise KeyError('Expected x/X, rounds/n, and shifts')
    mask = 0xFFFFFFFF
    x &= mask
    for _ in range(rounds):
        for op, amt in shifts:
            if op in ('l', 'L', '<<'):
                x ^= (x << amt) & mask
                x &= mask
            elif op in ('r', 'R', '>>'):
                x ^= (x >> amt)
                x &= mask
            else:
                raise ValueError('Unknown shift op')
    return float(x)

